  "python": "def pilot_policy(trace):
    # Extract the last action and label from trace
    last_action, last_label = trace[-1]
    action_name = last_action.name
    action_args = json.loads(last_action.arguments)
    label_subset = last_label.subset

    # Check for coordinator/send to delivery
    if action_name == 'coordinator/send' and action_args.get('target') == 'delivery':
        # Delivery only allows HARDSHIP; reject if PII present
        if 'PII' in label_subset:
            raise PolicyViolation('Delivery slot cannot contain PII')

    # Check for campaign/publish with include_case=True
    if action_name == 'campaign/publish' and action_args.get('include_case') == True:
        # Fundraising page cannot contain both PII and HARDSHIP
        if 'PII' in label_subset and 'HARDSHIP' in label_subset:
            raise PolicyViolation('Public fundraising page cannot contain both PII and HARDSHIP')

    # All other actions are permitted
    return None"
